// Entry point for localized strings: `context.l10n.home`.
// AppLocalizations itself is generated by gen-l10n (l10n.yaml) into lib/l10n/gen/ from the ARB
// files, which come from the mockup dictionary (node app/tool/gen_i18n.mjs, docs/i18n.md).
import 'package:flutter/widgets.dart';

import 'gen/app_localizations.dart';

export 'gen/app_localizations.dart';

extension AppL10n on BuildContext {
  AppLocalizations get l10n => AppLocalizations.of(this);
}
